import {NEEDS,assemble} from './puzzle.js';
const form=document.querySelector('#puzzle-form'),output=document.querySelector('#prompt-output');
for(const need of NEEDS){const label=document.createElement('label');label.className='choice';label.innerHTML=`<input type="checkbox" name="needs" value="${need.id}"><span class="choice-label"></span>`;label.querySelector('.choice-label').textContent=need.label;document.querySelector('#need-choices').append(label);}
let step=0,revision=0;
function readState(){const d=new FormData(form);return {needs:d.getAll('needs'),wording:d.get('wording'),color:d.get('color'),spacing:d.get('spacing'),support:d.get('support'),access:d.getAll('access'),priority:d.get('priority'),preserve:d.get('preserve'),detail:d.get('detail')};}
function update(){revision++;const state=readState(),result=assemble(state);output.value=result.text;const tags=document.querySelector('#piece-tags');tags.replaceChildren(...result.tags.map(t=>{const span=document.createElement('span');span.textContent=t;return span;}));const conflictNote=document.querySelector('#conflict-note');conflictNote.hidden=!result.conflicts.length;conflictNote.textContent=result.conflicts.length?'Certains choix demandent un essai comparé. Le prompt précise les points à arbitrer avec vous.':'';document.querySelector('#piece-count').textContent=`${result.tags.length} bloc${result.tags.length>1?'s':''}`;document.querySelector('#selection-count').textContent=state.needs.length?`${state.needs.length} besoin${state.needs.length>1?'s':''} sélectionné${state.needs.length>1?'s':''}`:'Aucun besoin sélectionné';document.querySelector('#copy-status').textContent='À coller avec votre synthèse dans l’IA de votre choix.';return result;}
function showStep(value,focus=true){step=value;document.querySelectorAll('[data-panel]').forEach((el,i)=>el.hidden=i!==step);document.querySelectorAll('[data-step]').forEach((el,i)=>{if(i===step)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});document.querySelector('#previous').hidden=step===0;document.querySelector('#next').hidden=step===3;document.querySelector('#selection-count').hidden=step!==0;document.querySelector('#next').innerHTML=['Mes préférences','Mon contexte','Ma touche personnelle'][step]+' <span aria-hidden="true">→</span>';if(focus)document.querySelector(`[data-panel="${step}"] h3`).focus();}
form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',update);form.addEventListener('change',update);
document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>showStep(Number(b.dataset.step))));document.querySelector('#next').addEventListener('click',()=>showStep(Math.min(3,step+1)));document.querySelector('#previous').addEventListener('click',()=>showStep(Math.max(0,step-1)));
document.querySelector('#copy').addEventListener('click',async()=>{const text=output.value,atRevision=revision,status=document.querySelector('#copy-status');try{if(!navigator.clipboard?.writeText)throw new Error('Presse-papiers indisponible');await navigator.clipboard.writeText(text);status.textContent=revision===atRevision?'Prompt copié ! Collez-le dans votre IA avec votre synthèse.':'Vos choix ont changé pendant la copie. Copiez à nouveau le prompt.';}catch{output.focus();output.select();status.textContent='Le texte est sélectionné. Utilisez Copier dans le menu, ou Ctrl+C / ⌘C.';}});
update();showStep(0,false);
// Lecture seule : même résultat que le champ visible, sans transmettre les choix.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_assembled_prompt',title:'Lire le prompt assemblé',description:'Retourne le prompt actuellement visible, construit à partir des choix de la personne. Ne modifie aucun choix et ne copie rien dans le presse-papiers.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new TypeError('Aucun paramètre attendu.');return {prompt:output.value};}})).catch(()=>{});}catch{/* Le générateur reste utilisable sans WebMCP. */}}
